"""Demo of the typed dataframe wrappers generated by tyframe.

Add a ``BaseDfModel`` class to ``examples/source``, run
``poe generate-example-wrappers`` and a type-hinted wrapper (e.g. ``TransactionPl``)
is generated in ``examples/generated``. The wrappers are then used in function
signatures, so the data flowing through each method is explicit.

Run from the repo root:

    uv run python -m examples.demo
"""

import polars as pl

from examples.generated import CustomerPl, CustomerSpendSummaryPl, RefundPl, RevenueByRegionPl, TransactionPl
from examples.source.models import Customer, Refund, Transaction
from tyframe.validation.polars import PolarsValidator

VALIDATOR = PolarsValidator()


def load_customers() -> CustomerPl:
    """Build a typed wrapper straight from model instances."""
    return CustomerPl(
        [
            Customer(id=1, name='Ada', last_name='Lovelace'),
            Customer(id=2, name='Grace', last_name='Hopper'),
            Customer(id=3, name='Alan', last_name='Turing'),
        ],
        VALIDATOR,
    )


def load_transactions() -> TransactionPl:
    return TransactionPl(
        [
            Transaction(customer_id=1, amount=120.0, region='EU'),
            Transaction(customer_id=1, amount=80.0, region='EU'),
            Transaction(customer_id=2, amount=250.0, region='US'),
            Transaction(customer_id=3, amount=45.0, region='EU'),
        ],
        VALIDATOR,
    )


def load_refunds() -> RefundPl:
    return RefundPl(
        [
            Refund(id=1, customer_id=2, amount=50.0, reason='duplicate charge'),
        ],
        VALIDATOR,
    )


def transactions_from_raw_df(raw: pl.DataFrame) -> TransactionPl:
    """Validate an existing polars dataframe against the model schema."""
    return TransactionPl(raw, VALIDATOR)


def big_transactions(transactions: TransactionPl, min_amount: float) -> TransactionPl:
    """Filter and sort; wrapper operations return the same typed wrapper, so calls chain."""
    filtered = transactions.filter(pl.col(transactions.amount) > min_amount)
    return filtered.sort(transactions.amount, ascending=False)


def revenue_by_region(transactions: TransactionPl) -> RevenueByRegionPl:
    """Aggregate into a typed report; column names come from the generated attributes."""
    report = (
        transactions.df.group_by(transactions.region)
        .agg(pl.col(transactions.amount).sum().alias(RevenueByRegionPl.revenue))
        .sort(RevenueByRegionPl.revenue, descending=True)
    )
    return RevenueByRegionPl(report, VALIDATOR)


def net_spend_per_customer(
    customers: CustomerPl,
    transactions: TransactionPl,
    refunds: RefundPl,
) -> CustomerSpendSummaryPl:
    """Compose several typed wrappers into a single typed report."""
    gross = (
        transactions.df.group_by(transactions.customer_id)
        .agg(pl.col(transactions.amount).sum().alias('spent'))
        .rename({transactions.customer_id: customers.id})
    )
    refunded = (
        refunds.df.group_by(refunds.customer_id)
        .agg(pl.col(refunds.amount).sum().alias('refunded'))
        .rename({refunds.customer_id: customers.id})
    )
    report = (
        customers.df.join(gross, on=customers.id, how='left')
        .join(refunded, on=customers.id, how='left')
        .with_columns(
            pl.col('spent').fill_null(0.0),
            pl.col('refunded').fill_null(0.0),
        )
        .with_columns((pl.col('spent') - pl.col('refunded')).alias(CustomerSpendSummaryPl.net_spend))
        .select(CustomerSpendSummaryPl.columns())
        .sort(CustomerSpendSummaryPl.net_spend, descending=True)
    )
    return CustomerSpendSummaryPl(report, VALIDATOR)


def vip_customers(
    customers: CustomerPl,
    transactions: TransactionPl,
    refunds: RefundPl,
    min_net_spend: float,
) -> CustomerPl:
    """A full pipeline that narrows a typed report into another typed wrapper."""
    report = net_spend_per_customer(customers, transactions, refunds)
    qualified = report.filter(pl.col(CustomerSpendSummaryPl.net_spend) >= min_net_spend)
    return qualified.select_to(CustomerPl)


def main() -> None:
    customers = load_customers()
    transactions = load_transactions().union(
        transactions_from_raw_df(pl.DataFrame({'customer_id': [3], 'amount': [25.0], 'region': ['US']})),
    )
    refunds = load_refunds()

    print('Transactions over 50, biggest first:')  # noqa: T201
    print(big_transactions(transactions, min_amount=50.0).df)  # noqa: T201

    revenue = revenue_by_region(transactions)
    print('Revenue by region:')  # noqa: T201
    print(revenue.df)  # noqa: T201
    top_region = revenue.first()
    print(f'Top region: {top_region.region} with revenue {top_region.revenue}')  # noqa: T201

    print('Net spend per customer:')  # noqa: T201
    print(net_spend_per_customer(customers, transactions, refunds).df)  # noqa: T201

    vips = vip_customers(customers, transactions, refunds, min_net_spend=100.0)
    print(f'VIP customers: {vips.count()}')  # noqa: T201
    for customer in vips.collect():
        print(f'  {customer.name} {customer.last_name}')  # noqa: T201
    print(f'Largest transaction: {big_transactions(transactions, min_amount=50.0).first()}')  # noqa: T201


if __name__ == '__main__':
    main()
